document.querySelector('#threatNum').style.color=threat>9?'#ff624f':threat>5?'#ffc46b':'#d8ff5e'}
function doReload(){if(!active||reloading||ammo===12||reserve<=0)return;reloading=true;reloadAt=performance.now()+1150;setTimeout(()=>{if(!active)return;const n=Math.min(12-ammo,reserve);ammo+=n;reserve-=n;reloading=false;updateHUD()},1150)}
function fire(){if(!active||reloading)return;const now=performance.now();if(now-fireAt<210)return;fireAt=now;if(ammo<=0){doReload();return}ammo--;updateHUD();
 let dx=aimPoint.x-player.position.x,dz=aimPoint.z-player.position.z,dist=Math.hypot(dx,dz);if(dist<.01){dx=0;dz=-1;dist=1}dx/=dist;dz/=dist;player.rotation.y=Math.atan2(dx,-dz);
 const startPoint=new THREE.Vector3(player.position.x+dx*.6,1.35,player.position.z+dz*.6),endPoint=new THREE.Vector3(player.position.x+dx*42,1.2,player.position.z+dz*42);muzzle.visible=true;setTimeout(()=>muzzle.visible=false,60);
 const line=new THREE.BufferGeometry().setFromPoints([startPoint,endPoint]);const tracer=new THREE.Line(line,new THREE.LineBasicMaterial({color:'#ffd98b',transparent:true,opacity:.8}));scene.add(tracer);setTimeout(()=>{scene.remove(tracer);line.dispose()},65);
 let hit=null,best=2.1;for(const z of zombies){if(!z.alive||!z.mesh.visible)continue;const vx=z.mesh.position.x-startPoint.x,vz=z.mesh.position.z-startPoint.z,t=vx*dx+vz*dz;if(t<0||t>42)continue;const off=Math.hypot(vx-dx*t,vz-dz*t);if(off<best){best=off;hit=z}}if(hit){hit.hp--;hit.mesh.rotation.z+=(Math.random()-.5)*.24;if(hit.hp<=0){hit.alive=false;hit.mesh.visible=false;score++;if(score%3===0)reserve=Math.min(72,reserve+6);updateHUD()}}}
function interact(){if(!active)return;let nearest=null,dist=2.75;for(const s of survivors){if(s.rescued)continue;const d=player.position.distanceTo(s.mesh.position);if(d<dist){dist=d;nearest=s}}if(nearest){nearest.rescued=true;nearest.mesh.visible=false;rescued++;notify('SURVIVOR RECRUITED  /  '+rescued+' OF 4');updateHUD();return}if(rescued>=4&&Math.hypot(player.position.x,player.position.z+39)<5){end(true)}}
function onPointer(e){const rect=canvas.getBoundingClientRect();pointer.x=(e.clientX-rect.left)/rect.width*2-1;pointer.y=-((e.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);const pt=new THREE.Vector3();if(raycaster.ray.intersectPlane(groundPlane,pt))aimPoint.copy(pt)}
canvas.addEventListener('pointermove',onPointer);canvas.addEventListener('pointerdown',e=>{if(e.button===0){shooting=true;onPointer(e);fire()}});window.addEventListener('pointerup',()=>shooting=false);window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys.add(k);if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='f'||k==='e')interact();if(k==='r')doReload();if(k===' '){shooting=true;fire()}});window.addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());if(e.key===' ')shooting=false});
// mobile thumb controls: virtual stick movement, fire, reload and rescue
let stickActive=false,stickX=0,stickY=0;const stick=document.querySelector('#stick');stick.addEventListener('pointerdown',e=>{stickActive=true;stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(stickActive)moveStick(e)});function moveStick(e){const r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let x=(e.clientX-cx)/43,y=(e.clientY-cy)/43,m=Math.max(1,Math.hypot(x,y));stickX=x/m*Math.min(1,m);stickY=y/m*Math.min(1,m);stick.style.setProperty('--sx',(stickX*25)+'px');stick.style.setProperty('--sy',(stickY*25)+'px');stick.style.setProperty('background',`radial-gradient(circle at ${50+stickX*35}% ${50+stickY*35}%,#d8ff5e88 0 18px,#10171377 19px)`)}stick.addEventListener('pointerup',()=>{stickActive=false;stickX=stickY=0;stick.style.background=''});document.querySelector('#fireTouch').addEventListener('pointerdown',e=>{e.preventDefault();shooting=true;aimPoint.set(player.position.x,0,player.position.z-15);const nearest=zombies.filter(z=>z.alive&&z.mesh.visible).sort((a,b)=>a.mesh.position.distanceTo(player.position)-b.mesh.position.distanceTo(player.position))[0];if(nearest)aimPoint.copy(nearest.mesh.position);fire()});window.addEventListener('pointerup',()=>shooting=false);document.querySelector('#reloadTouch').addEventListener('pointerdown',doReload);document.querySelector('#rescueTouch').addEventListener('pointerdown',interact);
document.querySelector('#deploy').addEventListener('click',start);document.querySelector('#retry').addEventListener('click',()=>location.reload());
const map=document.querySelector('#map'),mctx=map.getContext('2d');function drawMap(){mctx.clearRect(0,0,288,288);mctx.fillStyle='#28352a';mctx.fillRect(0,0,288,288);mctx.fillStyle='#50564e';mctx.fillRect(132,0,24,288);mctx.strokeStyle='#a5a17b';mctx.lineWidth=1;mctx.setLineDash([6,7]);mctx.beginPath();mctx.moveTo(144,0);mctx.lineTo(144,288);mctx.stroke();mctx.setLineDash([]);for(const [x,z,w,d] of buildings){mctx.fillStyle='#85816a';mctx.fillRect(144+x*2.7-w*1.35,144+z*2.7-d*1.35,w*2.7,d*2.7)}const coord=(v)=>144+v*2.7;mctx.fillStyle='#d8ff5e';mctx.beginPath();mctx.arc(coord(0),coord(-39),6,0,7);mctx.fill();for(const s of survivors){if(!s.rescued){mctx.fillStyle='#e7d8a1';mctx.fillRect(coord(s.mesh.position.x)-3,coord(s.mesh.position.z)-3,6,6)}}for(const z of zombies){if(z.alive&&z.mesh.visible){mctx.fillStyle='#e55744';mctx.beginPath();mctx.arc(coord(z.mesh.position.x),coord(z.mesh.position.z),2.6,0,7);mctx.fill()}}mctx.fillStyle='white';mctx.beginPath();mctx.arc(coord(player.position.x),coord(player.position.z),4.5,0,7);mctx.fill();mctx.strokeStyle='#fff';mctx.lineWidth=2;mctx.beginPath();mctx.moveTo(coord(player.position.x),coord(player.position.z));mctx.lineTo(coord(player.position.x)+Math.sin(player.rotation.y)*10,coord(player.position.z)-Math.cos(player.rotation.y)*10);mctx.stroke()}

